import { Problem } from '../types/index.ts';

// Helper to construct canonical LeetCode problem
export function createCanonicalProblem(
  id: string,
  title: string,
  difficulty: 'Easy' | 'Medium' | 'Hard',
  topic: string,
  pattern: string,
  leetcodeSlug: string,
  gfgSlug?: string,
  companyTags?: Array<'Google' | 'Microsoft' | 'JPMorgan'>
): Problem {
  return {
    id,
    title,
    difficulty,
    topic,
    pattern,
    leetcodeSlug,
    leetcodeUrl: `https://leetcode.com/problems/${leetcodeSlug}/`,
    leetcodeVerified: true,
    gfgUrl: gfgSlug
      ? `https://www.geeksforgeeks.org/problems/${gfgSlug}/1`
      : `https://www.geeksforgeeks.org/?s=${encodeURIComponent(title)}`,
    gfgVerified: Boolean(gfgSlug),
    lastVerifiedDate: '2026-08-15',
    companyEvidence: companyTags?.map((c) => ({
      company: c,
      verifiedDate: '2026-08-15',
      source: 'LeetCode / GFG Community Tag Registry',
    })),
  };
}

